export interface ExistingSetup {
  id: string;
  badRate: number | null;
  sessions: number;
  costPerSession: number | null;
}

const MIN_SESSIONS = 3;

function cmpNullLast(a: number | null, b: number | null): number {
  if (a === null && b === null) return 0;
  if (a === null) return 1;
  if (b === null) return -1;
  return a - b;
}

export function rankExisting(setups: ExistingSetup[], suspect: string, max: number): string[] {
  if (!(max > 0)) return [];
  return setups
    .filter((s) => s.id !== suspect && s.sessions >= MIN_SESSIONS)
    .sort(
      (a, b) =>
        cmpNullLast(a.badRate, b.badRate) ||
        cmpNullLast(a.costPerSession, b.costPerSession) ||
        (a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
    )
    .slice(0, Math.floor(max))
    .map((s) => s.id);
}

import { expect, test } from "bun:test";
import { rankExisting } from "../src/candidates/existing";

const s = (id: string, badRate: number | null, sessions = 5, costPerSession: number | null = 1) => ({
  id,
  badRate,
  sessions,
  costPerSession,
});

test("excludes suspect and thin setups", () => {
  expect(rankExisting([s("a", 0.1), s("b", 0.2, 2), s("c", 0.3)], "a", 5)).toEqual(["c"]);
});

test("sorts by badRate, null last, then cost, then id", () => {
  const r = rankExisting(
    [s("z", null), s("d", 0.1, 5, null), s("c", 0.1, 5, 2), s("b", 0.1, 5, 2), s("a", 0.5)],
    "x",
    10,
  );
  expect(r).toEqual(["b", "c", "d", "a", "z"]);
});

test("respects max", () => {
  expect(rankExisting([s("a", 0.1), s("b", 0.2)], "x", 1)).toEqual(["a"]);
  expect(rankExisting([s("a", 0.1)], "x", 0)).toEqual([]);
});
